import{_ as o,l as i,o as e,c as n,v as t,p as s,x as l,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"FSQ / LFQ","description":"","frontmatter":{"title":"FSQ / LFQ","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/fsq-lfq.md","filePath":"llm/fsq-lfq.md","lastUpdated":1789023840000}'),h={name:"llm/fsq-lfq.md"};function _(f,a,A,m,c,F){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="fsq-lfq" tabindex="-1">FSQ / LFQ <a class="header-anchor" href="#fsq-lfq" aria-label="Permalink to &quot;FSQ / LFQ&quot;">​</a></h1><div class="epigraph"><p>码本学习会崩溃。把每个维直接量化到固定网格，或对符号做无查找量化，词表变成设计出来的，而不是抢着用的。</p><footer>—— Mentzer 等 FSQ；Yu 等 MAGVIT-v2 的 Lookup-Free Quantization</footer></div><p><a href="/llm/vqgan">上一课</a>仍要维护可学习码本。Mentzer 等人的有限标量量化（FSQ）对每个通道独立量化到少量水平；Yu 等人的 LFQ 用符号位组合出词表，前向无码本查找。缺口是量化器的稳定性。后课连续对离散默认：离散侧不一定再背一个大码本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VQ 的最近邻与 EMA 码本在大数据上仍会死码、要调承诺损失。FSQ：令 \\(z\\in\\mathbb{R}^{d}\\)，每维量化到 \\(L\\) 档，词表大小 \\(L^{d}\\)（\\(d\\) 很小）。没有可学习 \\(e_k\\)，崩溃被结构禁止。LFQ：对二元或低比特维做查找无关的整数编码，同样避免码本抢占。二者用重构 + 辅助损失训练编码器/解码器。</p><p>权衡：网格量化在感知上可能弱于精心学的码本，要靠解码器与损失补；词表大小由网格组合爆炸，维数必须小。</p><p><span class="marginnote">FSQ 的「词表」是笛卡尔网格，LM 看到的 ID 是网格坐标的编码。ID 的邻域结构与语义邻域不必一致。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选 \\(L\\) 与通道数使词表与序列长度可接 LM。训练盯重构与有效使用率（网格点是否都被访问）。接自回归时，ID 映射必须冻结，否则旧检查点的 token 失效。与 VQGAN 比，GAN 仍可加在解码器上，量化器本身更简单。</p>',9)),(e(),s(E,null,{default:l(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ZE%5B%22%E8%BF%9E%E7%BB%AD%20z%22%5D%20--%3E%20FSQ%5B%22%E9%80%90%E7%BB%B4%E7%BD%91%E6%A0%BC%E9%87%8F%E5%8C%96%22%5D%0A%20%20ZE%20--%3E%20LFQ%5B%22%E6%97%A0%E6%9F%A5%E6%89%BE%E6%AF%94%E7%89%B9%E9%87%8F%E5%8C%96%22%5D%0A%20%20FSQ%20--%3E%20ID%5B%22%E5%9B%BA%E5%AE%9A%E8%AF%8D%E8%A1%A8%20ID%22%5D%0A%20%20LFQ%20--%3E%20ID%0A%20%20ID%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可学习码本是聚类：热门模式抢走码字。固定网格把容量均匀铺在坐标箱上，编码器必须把语义放进这些箱的组合。这更稳，但把几何负担全交给编码器。LM 建模的是箱下标的语法，不是码向量的余弦。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不是所有生成系统都要离散。下一课把连续潜变量（扩散/流）与离散 token 两条路对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FSQ / LFQ 用固定网格或无查找编码避免码本崩溃。</li><li>词表是设计量；ID 邻域不等于语义邻域。</li><li>稳定性换来的负担在编码器与解码器。</li><li>出处：Mentzer 等 FSQ；Yu 等 MAGVIT-v2 / LFQ。</li></ul>',6))])}const Q=o(h,[["render",_]]);export{q as __pageData,Q as default};
